-- 0018 系統預設任務的起始內容（規格 09 §5.2、§10.2 #5）：幼貓／壯貓／老貓各一套，讓中途選「先用系統預設任務」時有東西可以用。
-- 內容和 src/lib/ai/tasks.ts 的 fallbackTaskDraft 相同（AI 沒回應時的固定草稿），是暫定版，之後由 MeowHQ 管理員和渝茜一起調整（#58）。
-- 這個年齡層已經有啟用中的預設任務就不動（不會蓋掉 MeowHQ 改過的內容）。可重複執行；只動 meow_ 開頭的物件（AGENTS.md §7）。
-- ⚠ 執行前須經發起人確認（AGENTS.md §7.4）。
insert into public.meow_task_templates (life_stage, title, content, is_active)
select v.life_stage, v.title, v.content, true
  from (values
  ('kitten', '幼貓的預設任務', '{"tasks":[{"id":"kitten_1","day":1,"title":"第一個晚上","story":"牠剛到新家，一整個下午都躲在床底不出來。","action":"hide","needs":["hiding_spot"],"options":[{"text":"放好水和貓砂，給牠時間慢慢出來","good":true,"feedback":"對！剛到新家的貓需要時間，先讓牠自己探索最安心。"},{"text":"把牠從床底抱出來安撫","good":false,"feedback":"強迫抱出來會讓牠更害怕，等牠準備好再互動。"}]},{"id":"kitten_2","day":2,"title":"凌晨暴衝","story":"凌晨三點，牠在走廊來回衝刺，把你吵醒了。","action":"zoomies","needs":[],"options":[{"text":"睡前陪牠玩 15 分鐘逗貓棒","good":true,"feedback":"睡前消耗體力，晚上會睡得比較安穩。"},{"text":"起床大聲制止牠","good":false,"feedback":"大聲制止會讓牠緊張，也可能變成討關注的方式。"}]},{"id":"kitten_3","day":3,"title":"桌上的杯子","story":"牠跳上書桌，把你的水杯撥到地上。","action":"jump_high","needs":["high_place"],"options":[{"text":"把易碎物收好，給牠一個可以跳的貓跳台","good":true,"feedback":"給牠合適的高處，比禁止更有效。"},{"text":"噴水嚇牠","good":false,"feedback":"噴水會破壞信任，牠只會學到趁你不在時再跳。"}]},{"id":"kitten_4","day":4,"title":"啃電線","story":"牠在咬充電線。","action":"none","needs":[],"options":[{"text":"把電線收好或套上保護套","good":true,"feedback":"幼貓愛咬東西，先把危險的東西收起來最重要。"},{"text":"沒關係，牠長大就不咬了","good":false,"feedback":"咬電線可能觸電，要先處理環境。"}]},{"id":"kitten_5","day":5,"title":"吐毛球","story":"早上起床，發現牠在地上吐了一團毛球。","action":"hairball","needs":[],"options":[{"text":"清乾淨，多幫牠梳毛；常常吐就帶去給獸醫看","good":true,"feedback":"偶爾吐毛球很常見，梳毛能減少；頻繁嘔吐要看醫生。"},{"text":"馬上餵人吃的胃藥","good":false,"feedback":"人的藥可能對貓有害，不要自己餵藥。"}]}]}'::jsonb),
  ('adult', '成貓的預設任務', '{"tasks":[{"id":"adult_1","day":1,"title":"第一個晚上","story":"牠剛到新家，一整個下午都躲在床底不出來。","action":"hide","needs":["hiding_spot"],"options":[{"text":"放好水和貓砂，給牠時間慢慢出來","good":true,"feedback":"對！剛到新家的貓需要時間，先讓牠自己探索最安心。"},{"text":"把牠從床底抱出來安撫","good":false,"feedback":"強迫抱出來會讓牠更害怕，等牠準備好再互動。"}]},{"id":"adult_2","day":2,"title":"凌晨暴衝","story":"凌晨三點，牠在走廊來回衝刺，把你吵醒了。","action":"zoomies","needs":[],"options":[{"text":"睡前陪牠玩 15 分鐘逗貓棒","good":true,"feedback":"睡前消耗體力，晚上會睡得比較安穩。"},{"text":"起床大聲制止牠","good":false,"feedback":"大聲制止會讓牠緊張，也可能變成討關注的方式。"}]},{"id":"adult_3","day":3,"title":"桌上的杯子","story":"牠跳上書桌，把你的水杯撥到地上。","action":"jump_high","needs":["high_place"],"options":[{"text":"把易碎物收好，給牠一個可以跳的貓跳台","good":true,"feedback":"給牠合適的高處，比禁止更有效。"},{"text":"噴水嚇牠","good":false,"feedback":"噴水會破壞信任，牠只會學到趁你不在時再跳。"}]},{"id":"adult_4","day":4,"title":"抓沙發","story":"牠開始抓沙發的扶手。","action":"scratch_furniture","needs":["sofa"],"options":[{"text":"在沙發旁放一個貓抓板","good":true,"feedback":"磨爪是本能，給牠可以抓的地方就好。"},{"text":"幫牠去爪","good":false,"feedback":"去爪會傷害貓，台灣的中途幾乎都不接受。"}]},{"id":"adult_5","day":5,"title":"吐毛球","story":"早上起床，發現牠在地上吐了一團毛球。","action":"hairball","needs":[],"options":[{"text":"清乾淨，多幫牠梳毛；常常吐就帶去給獸醫看","good":true,"feedback":"偶爾吐毛球很常見，梳毛能減少；頻繁嘔吐要看醫生。"},{"text":"馬上餵人吃的胃藥","good":false,"feedback":"人的藥可能對貓有害，不要自己餵藥。"}]}]}'::jsonb),
  ('senior', '老貓的預設任務', '{"tasks":[{"id":"senior_1","day":1,"title":"第一個晚上","story":"牠剛到新家，一整個下午都躲在床底不出來。","action":"hide","needs":["hiding_spot"],"options":[{"text":"放好水和貓砂，給牠時間慢慢出來","good":true,"feedback":"對！剛到新家的貓需要時間，先讓牠自己探索最安心。"},{"text":"把牠從床底抱出來安撫","good":false,"feedback":"強迫抱出來會讓牠更害怕，等牠準備好再互動。"}]},{"id":"senior_2","day":2,"title":"凌晨暴衝","story":"凌晨三點，牠在走廊來回衝刺，把你吵醒了。","action":"zoomies","needs":[],"options":[{"text":"睡前陪牠玩 15 分鐘逗貓棒","good":true,"feedback":"睡前消耗體力，晚上會睡得比較安穩。"},{"text":"起床大聲制止牠","good":false,"feedback":"大聲制止會讓牠緊張，也可能變成討關注的方式。"}]},{"id":"senior_3","day":3,"title":"跳不上沙發","story":"牠想跳上沙發，試了兩次都沒跳上去。","action":"sofa","needs":["sofa"],"options":[{"text":"在沙發旁放一個矮凳當階梯","good":true,"feedback":"老貓關節比較弱，降低高度能讓牠繼續待在喜歡的地方。"},{"text":"把牠抱上去就好","good":false,"feedback":"偶爾可以，但牠自己上不去時會很挫折，環境調整比較好。"}]},{"id":"senior_4","day":4,"title":"抓沙發","story":"牠開始抓沙發的扶手。","action":"scratch_furniture","needs":["sofa"],"options":[{"text":"在沙發旁放一個貓抓板","good":true,"feedback":"磨爪是本能，給牠可以抓的地方就好。"},{"text":"幫牠去爪","good":false,"feedback":"去爪會傷害貓，台灣的中途幾乎都不接受。"}]},{"id":"senior_5","day":5,"title":"吐毛球","story":"早上起床，發現牠在地上吐了一團毛球。","action":"hairball","needs":[],"options":[{"text":"清乾淨，多幫牠梳毛；常常吐就帶去給獸醫看","good":true,"feedback":"偶爾吐毛球很常見，梳毛能減少；頻繁嘔吐要看醫生。"},{"text":"馬上餵人吃的胃藥","good":false,"feedback":"人的藥可能對貓有害，不要自己餵藥。"}]}]}'::jsonb)
  ) as v (life_stage, title, content)
 where not exists (select 1 from public.meow_task_templates t where t.life_stage = v.life_stage and t.is_active);
